"""Notebook extension for source-bound result attribution."""
CSS=r"""
.v4-page{overflow-wrap:anywhere}.v4-lead{max-width:850px;margin:26px 0}.v4-lead h2{font:42px/1.12 Georgia,serif;letter-spacing:-1px;margin:12px 0}.v4-hand{font:26px Caveat,cursive;color:var(--blue)}.v4-summary{display:flex;gap:30px;flex-wrap:wrap;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:18px 0;margin:24px 0}.v4-summary strong{display:block;font:30px Georgia,serif}.v4-summary small{color:var(--muted)}.v4-controls{display:flex;gap:18px;flex-wrap:wrap;margin:22px 0}.v4-controls label{flex:1;min-width:200px;font-size:12px}.v4-controls select{display:block;width:100%;margin-top:8px;padding:11px;border:1px solid #c9c4b6;background:var(--white);color:var(--ink)}.v4-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(250px,1fr);gap:25px}.v4-page .research-figure{min-width:0}.v4-chart{width:100%;height:auto;display:block}.v4-bar{cursor:pointer}.v4-bar:focus{outline:none;stroke:#152c35;stroke-width:3}.v4-readout{padding:16px 0;border-top:1px dashed #b8b098;font-size:13px}.v4-readout h3{font:28px Caveat,cursive;color:var(--blue);margin:8px 0}.v4-readout dl{display:grid;grid-template-columns:1fr auto;gap:9px}.v4-readout dd{margin:0;font-variant-numeric:tabular-nums}.v4-cell-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:15px 0}.v4-cell{padding:13px 8px;border:1px solid #d8d4c6;background:var(--white);text-align:left;color:var(--ink);min-height:68px}.v4-cell[aria-pressed=true]{outline:2px solid var(--blue);outline-offset:0}.v4-cell small{display:block;color:var(--muted);font-size:10px}.v4-cell strong{font-size:12px}.v4-sequence{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0 18px}.v4-token{font-size:11px;border:1px solid #bcc9d9;border-radius:3px;padding:7px 9px;background:#edf1fa}.v4-token.initial{background:#eeeae1;border-color:#d7d1c4}.v4-status{margin:22px 0;padding:18px 0;border-top:1px solid var(--line);font-size:13px}.v4-status li{margin:9px 0}.v4-pin{background:#fffbed;border:1px solid #d4cbb0;padding:18px;min-width:0;overflow-wrap:anywhere}.v4-pins{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:22px 0}.v4-pin summary{font-size:11px}.v4-pin pre{white-space:pre-wrap;font-size:10px;overflow-wrap:anywhere}.v4-note-link{padding:15px 0;font-size:13px;border-bottom:1px dashed #b8b098;margin-bottom:20px}.v4-note-link button{border:0;background:transparent;color:var(--blue);text-decoration:underline;cursor:pointer;font:inherit}.v4-page details{margin-top:18px}.v4-page details p{font-size:12px}.v4-total{font-size:12px;color:var(--muted)}@media(max-width:760px){.v4-lead h2{font-size:33px}.v4-grid,.v4-pins{grid-template-columns:1fr}.v4-controls label{min-width:0;flex-basis:100%}.v4-summary{gap:20px}.v4-summary strong{font-size:25px}.v4-cell{padding:10px 5px}.v4-cell strong{font-size:10px}.v4-cell-grid{gap:5px}.v4-page .research-figure{padding:17px}}
"""
JS=r"""
let V4=null,V4Error=null;
const V4S={comparison:'starting',dimension:'series',group:null,cell:0,task:0,pins:[],seq:0};
const v4Names={starting:'SFT versus starting policy',static:'SFT versus training-selected static',hidden:'SFT versus feedback hidden',rl_parent_17:'RL seed 17 versus its SFT parent',rl_parent_29:'RL seed 29 versus its SFT parent',rl_parent_43:'RL seed 43 versus its SFT parent'};
function v4Label(id){if(id.includes('A100_SXM'))return 'A100 SXM 80GB';if(id.includes('A100_40'))return 'A100 40GB';return id}
function v4Comparison(){return V4.comparisons.find(c=>c.id===V4S.comparison)||V4.comparisons[0]}
function v4Selected(){let c=v4Comparison(),rows=c.groups[V4S.dimension];return rows.find(r=>r.id===V4S.group)||rows[0]}
function v4Number(n){return (n>0?'+':'')+fmt(n,8)}
function v4Chart(c){
 const rows=c.groups[V4S.dimension],w=window.innerWidth<760?Math.max(250,window.innerWidth-70):760,h=110+rows.length*82,L=30,R=25,zero=w/2,max=Math.max(...rows.map(r=>Math.abs(r.weighted_contribution)),1e-8),length=w/2-35;
 let body='<line x1="'+zero+'" y1="25" x2="'+zero+'" y2="'+(h-38)+'" stroke="#8c9a99"/><text x="'+(zero-15)+'" y="17" text-anchor="end" fill="#187666" font-size="12">Lower loss</text><text x="'+(zero+15)+'" y="17" fill="#9b5b20" font-size="12">Higher loss</text>';
 rows.forEach((r,i)=>{let y=55+i*82,bar=Math.abs(r.weighted_contribution)/max*length,x=r.weighted_contribution<0?zero-bar:zero,selected=v4Selected().id===r.id,label=V4S.dimension==='horizon'?r.id+' days':v4Label(r.id);body+='<g class="v4-bar" tabindex="0" role="button" data-v4-group="'+esc(r.id)+'" aria-label="'+esc(label+', contribution '+v4Number(r.weighted_contribution)+', '+r.n_cells+' cells')+'" aria-pressed="'+selected+'"><text x="30" y="'+(y+3)+'" fill="#172d34" font-size="13">'+esc(label)+'</text><rect x="'+x+'" y="'+(y+13)+'" width="'+Math.max(bar,2)+'" height="19" fill="'+(r.weighted_contribution<=0?'#187666':'#a46024')+'" opacity="'+(selected?1:.75)+'"/><text x="'+zero+'" y="'+(y+52)+'" text-anchor="middle" fill="#52646a" font-size="11">'+v4Number(r.weighted_contribution)+' · '+r.n_cells+' cells</text></g>'});
 body+='<text x="'+zero+'" y="'+(h-8)+'" text-anchor="middle" fill="#52646a" font-size="11">Contribution to mean pinball difference</text>';
 return '<svg id="v4-contribution-chart" class="v4-chart" role="group" aria-label="Exact contributions to the selected comparison" viewBox="0 0 '+w+' '+h+'">'+body+'</svg>'
}
function v4Sequence(task,key,label){return '<div><strong>'+label+'</strong><div class="v4-sequence">'+task[key].map((id,i)=>'<span class="v4-token '+(i<2?'initial':'')+'">'+(i+1)+'. '+esc(id.replace('last_value_empirical','empirical').replace('last_value','persistence'))+'</span>').join('')+'</div></div>'}
function v4Pins(){return V4S.pins.length?'<section aria-label="Pinned research observations"><h3 class="v4-hand">Keep the evidence in the margin.</h3><div class="v4-pins">'+V4S.pins.map(p=>'<article class="v4-pin" data-v4-pin="'+p.id+'"><button data-v4-remove="'+p.id+'" aria-label="Remove research note '+p.id+'">Remove</button><p>'+esc(p.label)+'</p><strong>'+v4Number(p.snapshot.weighted_contribution??p.snapshot.delta)+'</strong><details id="v4-pin-detail-'+p.id+'"><summary>Exact values and source</summary><pre>'+esc(JSON.stringify(p,null,2))+'</pre></details></article>').join('')+'</div></section>':''}
function reviewFindings(){
 if(!V4)return '<div class="empty"><h2>'+(V4Error?'Research findings could not load.':'Opening the result notebook…')+'</h2><p>Pricing remains available. No substitute research values are displayed.</p><button id="v4-retry">Retry findings</button></div>';
 const c=v4Comparison(),g=v4Selected(),m=V4.mechanism,task=m.tasks[Math.min(V4S.task,m.tasks.length-1)],cell=c.cells[Math.min(V4S.cell,c.cells.length-1)],r=V4.readiness;
 return '<div class="v4-page"><div class="v4-lead"><div class="v4-hand">What changed—and what did not?</div><h2>A gain is made of smaller stories.</h2><p>Follow the measured difference from an aggregate score to its series, dates and decisions. These are the same 12 retrospective cells across three dependent dates.</p></div><div class="v4-controls"><label>Compare saved results<select id="v4-comparison">'+V4.comparisons.map(x=>'<option value="'+x.id+'" '+(x.id===c.id?'selected':'')+'>'+v4Names[x.id]+'</option>').join('')+'</select></label><label>Explain the difference by<select id="v4-dimension">'+[['series','GPU series'],['origin','Forecast origin'],['horizon','Forecast horizon']].map(([id,title])=>'<option value="'+id+'" '+(V4S.dimension===id?'selected':'')+'>'+title+'</option>').join('')+'</select></label></div><div class="v4-summary"><div><strong id="v4-candidate">'+fmt(c.candidate_pinball,8)+'</strong><small>Candidate mean pinball ↓</small></div><div><strong>'+fmt(c.reference_pinball,8)+'</strong><small>Reference mean pinball</small></div><div><strong id="v4-delta">'+v4Number(c.delta)+'</strong><small>Candidate − reference · n='+c.n_cells+'</small></div></div><div class="v4-grid"><section class="research-figure"><div class="eyebrow">01 / WHERE THE DIFFERENCE COMES FROM</div><h3>Every part adds up.</h3><p class="sub">Select a mark. Green lowers loss; amber raises it. Each contribution includes its share of the '+c.n_cells+' scored cells.</p>'+v4Chart(c)+'<p class="v4-total" id="v4-sum">Sum of contributions: '+v4Number(c.groups[V4S.dimension].reduce((a,r)=>a+r.weighted_contribution,0))+'</p><details id="v4-formula"><summary>How this is calculated</summary><p>Contribution = group cells ÷ total cells × (candidate loss − reference loss). No cell counts as an independent market experiment. The 15-cell numerical grid is excluded.</p></details></section><aside class="research-figure v4-readout"><div class="eyebrow">MARGIN NOTE</div><h3>'+esc(V4S.dimension==='horizon'?g.id+' days ahead':v4Label(g.id))+'</h3><p>This group '+(g.delta<0?'improved':g.delta>0?'worsened':'tied')+' the candidate’s loss relative to the selected reference.</p><dl><dt>Candidate loss</dt><dd>'+fmt(g.candidate_pinball,8)+'</dd><dt>Reference loss</dt><dd>'+fmt(g.reference_pinball,8)+'</dd><dt>Weighted contribution</dt><dd id="v4-selected-contribution">'+v4Number(g.weighted_contribution)+'</dd><dt>Scored cells</dt><dd>'+g.n_cells+'</dd><dt>Candidate coverage</dt><dd>'+Math.round(g.candidate_coverage*g.n_cells)+' / '+g.n_cells+'</dd><dt>Candidate interval width</dt><dd>'+fmt(g.candidate_width,6)+'</dd></dl><p class="sub">'+(g.baseline_pinball===0?'Persistence loss is zero here; relative skill against it is undefined.':'Coverage and width are descriptive on this small dependent sample.')+'</p><button id="v4-pin-group">Pin this result</button><details id="v4-source"><summary>Exact source and scope</summary><p>Study '+esc(V4.study_id)+'; source '+esc(V4.source_sha)+'. Archive SHA-256 '+esc(V4.archive_sha256)+'. <a href="/api/review-v4">Download the exact derived artifact</a>.</p></details></aside></div><section class="research-figure"><div class="eyebrow">02 / INSPECT THE ACTUAL CELLS</div><h3>Twelve cells, not twelve independent experiments.</h3><div class="v4-cell-grid">'+c.cells.map((x,i)=>'<button class="v4-cell" data-v4-cell="'+i+'" aria-pressed="'+(V4S.cell===i)+'"><small>'+esc(x.origin)+' · '+x.horizon_days+'d</small><strong>'+esc(v4Label(x.series_id))+'</strong><small>Δ '+v4Number(x.delta)+'</small></button>').join('')+'</div><p id="v4-cell-note">'+esc(cell.origin)+' · '+esc(v4Label(cell.series_id))+' · '+cell.horizon_days+' days: candidate '+fmt(cell.candidate_loss,8)+', reference '+fmt(cell.reference_loss,8)+'.</p><button id="v4-pin-cell">Pin this cell</button></section><section class="research-figure"><div class="eyebrow">03 / WHAT DID FEEDBACK CHANGE?</div><h3>Different order. The same final choice.</h3><p>'+m.changed_orders+' of '+m.n_tasks+' orders changed; '+m.same_terminal_choices+' final choices stayed the same. A fixed four-tree portfolio reconstructs '+m.compressed_loss_matches+' recorded task losses.</p><label for="v4-task">Inspect a saved task</label><select id="v4-task">'+m.tasks.map((x,i)=>'<option value="'+i+'" '+(V4S.task===i?'selected':'')+'>'+x.origin+' · '+esc(v4Label(x.series_ids[0]))+'</option>').join('')+'</select>'+v4Sequence(task,'feedback_order','Feedback visible')+v4Sequence(task,'hidden_order','Feedback hidden')+'<p id="v4-terminal">Final choices: '+esc(task.feedback_choice)+' / '+esc(task.hidden_choice)+'. Pinball: '+fmt(task.feedback_pinball,8)+' / '+fmt(task.hidden_pinball,8)+'.</p><p class="sub">The portfolio comparison was identified after evaluation. Raw quantile prediction equality remains unknown: equal losses alone do not prove identical predictions. <a href="/api/review-v4">Inspect ties and reconstruction checks</a>.</p></section>'+v4Pins()+'<section class="v4-status"><h3 class="v4-hand">The next page is still being written.</h3><ul><li>Further training is gated: '+r.training_tasks+' training tasks, '+r.zero_reward_variation_tasks+' with no reachable reward variation. No new optimizer updates.</li><li>The new weekly selector panel is registered separately; issuance and outcomes remain pending.</li><li>The existing November 16/18/22 baseline–Chronos commitment remains unchanged and cannot score before November 23 UTC.</li></ul><p><a href="/api/review-v4/protocols">Registered protocols and resource limits</a> · <a href="https://github.com/howdymary/compute-forecasting/blob/compute-observatory/docs/review-v4.md" target="_blank" rel="noopener">Methods and public reproduction</a></p></section></div>'
}
function bindReview(){
 const rerender=()=>render();if($('#v4-retry')){$('#v4-retry').onclick=loadReview;return}
 if(!$('#v4-comparison'))return;
 $('#v4-comparison').onchange=e=>{V4S.comparison=e.target.value;V4S.group=null;rerender()};
 $('#v4-dimension').onchange=e=>{V4S.dimension=e.target.value;V4S.group=null;rerender()};
 document.querySelectorAll('[data-v4-group]').forEach(el=>{const select=()=>{V4S.group=el.dataset.v4Group;if(V4S.dimension==='origin'){let i=V4.mechanism.tasks.findIndex(t=>t.origin===V4S.group);if(i>=0)V4S.task=i}rerender()};el.onpointerdown=select;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select()}}});
 document.querySelectorAll('[data-v4-cell]').forEach(el=>el.onclick=()=>{V4S.cell=+el.dataset.v4Cell;const c=v4Comparison().cells[V4S.cell],i=V4.mechanism.tasks.findIndex(t=>t.origin===c.origin&&t.series_ids.includes(c.series_id));if(i>=0)V4S.task=i;rerender()});
 $('#v4-task').onchange=e=>{V4S.task=+e.target.value;rerender()};
 function pin(kind,snapshot,label){V4S.pins.push({id:++V4S.seq,kind,label,comparison:V4S.comparison,cohort_id:v4Comparison().cohort_id,source_sha:V4.source_sha,archive_sha256:V4.archive_sha256,snapshot:JSON.parse(JSON.stringify(snapshot))});if(V4S.pins.length>3)V4S.pins.shift();rerender()}
 $('#v4-pin-group').onclick=()=>pin('derived_group',v4Selected(),v4Names[V4S.comparison]+' · '+v4Label(v4Selected().id));
 $('#v4-pin-cell').onclick=()=>{const c=v4Comparison().cells[V4S.cell];pin('derived_cell',c,c.origin+' · '+v4Label(c.series_id)+' · '+c.horizon_days+'d')};
 document.querySelectorAll('[data-v4-remove]').forEach(el=>el.onclick=()=>{V4S.pins=V4S.pins.filter(p=>p.id!==+el.dataset.v4Remove);rerender()})
}
const v4PreviousRender=render,v4PreviousAtlas=researchAtlas,v4PreviousDownloads=downloads;
researchAtlas=function(){return '<div class="v4-note-link"><strong>New finding:</strong> the same four-tree portfolio reconstructs all four operational task choices. <button data-research="review">Follow the evidence →</button></div>'+v4PreviousAtlas()};
render=function(){let active=document.activeElement,group=active?.dataset?.v4Group,cell=active?.dataset?.v4Cell;v4PreviousRender();if(view==='research'&&researchTab==='review'){bindReview();const target=group?[...document.querySelectorAll('[data-v4-group]')].find(e=>e.dataset.v4Group===group):cell?document.querySelector('[data-v4-cell="'+cell+'"]'):null;target?.focus({preventScroll:true})}};
downloads=function(){return v4PreviousDownloads()+'<section class="research-figure"><h3>Review v4</h3><p><a href="/api/review-v4">Reconstructed mechanisms and matched contributions</a> · <a href="/api/review-v4/protocols">Registered successor experiments</a></p></section>'};
async function loadReview(){V4Error=null;try{let v=await fetchJson('/api/review-v4');if(v.schema_version!==4||v.mechanism.n_cells!==12)throw Error('Unexpected review scope');V4=v}catch(e){V4Error=e}if(P&&view==='research'&&researchTab==='review')render()}
loadReview();
"""
def enhance(html):
    if html.count("[['visual','Research atlas']")!=1:raise ValueError("Research tab insertion target changed")
    html=html.replace("[['visual','Research atlas']","[['review','Findings'],['visual','Research atlas']")
    if html.count("({visual:researchAtlas,results,")!=1:raise ValueError("Research renderer target changed")
    html=html.replace("({visual:researchAtlas,results,","({review:reviewFindings,visual:researchAtlas,results,")
    return html.replace("</style>",CSS+"</style>").replace("</script>",JS+"</script>")
